//! The frozen eid-circuits circuits, as bindings for `noir-zk-backend`.
//!
//! [`circuits`] is generated by `noir-zk-codegen` from `circuits/manifest.toml`
//! and `resources/` (written by `noir-zk freeze`, see `mise run freeze`). Every
//! active circuit gets typed `Inputs` / `Outputs` and a marker type
//! implementing `Circuit`, `CircuitId` (its Chonk key embedded) and `App` or
//! `Kernel`, plus [`circuits::REGISTRY`] and [`circuits::Registry`] (static
//! dispatch from a runtime-selected label to its circuit type).
//!
//! A document folds as
//! `DSC -> kernel_dsc -> SOD -> kernel_sod -> envelope -> kernel_envelope -> kernel_tail -> kernel_hiding`
//! with `noir_zk_backend::fold::Folding`, which type-checks that chain; the
//! proof verifies with `noir_zk_backend::fold::verify::<KernelHiding>`.
//! Kernels only link to the outputs they take. Starting with the SOD step
//! is a compile error (`KernelSod::Prev` is `kernel_dsc`'s outputs, not `()`):
//!
//! ```compile_fail
//! # use eid_circuits::circuits::kernel_sod::KernelSod;
//! # fn chain<A: noir_zk_core::Artifacts>(a: &A) {
//! let _ = noir_zk_backend::fold::Folding::new(a)
//!     .app(KernelSod::select("sod_ecdsa_p256_sha256_tbs1000", "").unwrap());
//! # }
//! ```
//!
//! Bytecode isn't embedded (about 730 MB): [`artifacts`] fetches it from a
//! store and rejects it unless it hashes to the pinned value.

use noir_zk_backend::{ArtifactStore, Frozen};
use noir_zk_core::codec::field_from_be_bytes_canonical;
use noir_zk_core::{Error, Field};

pub use noir_zk_backend::DirStore;

/// Where releases publish the circuit packs: `<pack>@<version>.tar.gz`,
/// `catalog@<version>.json`, `vk-tree@<version>.json`, and `catalog.json`
/// (the latest release's catalog). Every asset in a pack is checked against
/// its pin, so this host is a mirror, not a trust anchor.
pub const PACKS_URL: &str = "https://circuits.zk-eid.dev";
#[cfg(feature = "http")]
pub use noir_zk_backend::HttpStore;

/// Generated from the frozen registry (see the crate docs).
#[allow(missing_docs, clippy::all)]
pub mod circuits {
    include!(concat!(env!("OUT_DIR"), "/circuits.rs"));
}

/// Circuits compiled and embedded at build time (feature `bundled`).
#[cfg(feature = "bundled")]
pub mod bundled {
    use noir_zk_backend::ArtifactStore;
    use noir_zk_core::Error;

    include!(concat!(env!("OUT_DIR"), "/bundled.rs"));

    /// The embedded assets as a store; [`artifacts`](crate::artifacts)
    /// still checks each against its pin.
    pub struct BundledStore;

    impl ArtifactStore for BundledStore {
        fn fetch(&self, asset: &str) -> Result<Vec<u8>, Error> {
            ASSETS
                .iter()
                .find(|(name, _)| *name == asset)
                .map(|(_, bytes)| bytes.to_vec())
                .ok_or_else(|| Error::Artifact(format!("{asset} is not bundled")))
        }
    }
}

/// The frozen circuits with bytecode from `store`, for [`prove_document`].
pub fn artifacts<S: ArtifactStore>(store: S) -> Result<Frozen<S>, Error> {
    Frozen::new(circuits::REGISTRY, &circuits::VK_TREE_ROOT, store)
}

/// The verification key tree root a document proof must carry.
pub fn vk_tree_root() -> Field {
    field_from_be_bytes_canonical(&circuits::VK_TREE_ROOT, "vk tree root").unwrap_or_default()
}
#[cfg(test)]
mod tests {
    use super::*;

    /// Every bundled asset passes the pin check (feature `bundled`).
    #[cfg(feature = "bundled")]
    #[test]
    fn bundled_assets_match_their_pins() {
        use noir_zk_core::Artifacts;
        let frozen = artifacts(bundled::BundledStore).unwrap();
        for (asset, _) in bundled::ASSETS {
            let label = asset.split('@').next().unwrap();
            assert!(frozen.bytecode_b64(label).is_ok(), "{asset}");
        }
    }
    use noir_zk_core::registry::{active, Status};
    use noir_zk_core::{ChonkRole, Circuit, CircuitId, ProofSystem};

    #[test]
    fn registry_is_complete() {
        let active: Vec<_> = circuits::REGISTRY
            .iter()
            .filter(|e| e.status == Status::Active)
            .collect();
        assert_eq!(active.len(), 301);
        assert_eq!(
            active
                .iter()
                .filter(|e| e.system == ProofSystem::Chonk(ChonkRole::Kernel))
                .count(),
            4
        );
        assert_eq!(
            active
                .iter()
                .filter(|e| e.system == ProofSystem::Chonk(ChonkRole::Hiding))
                .count(),
            1
        );
        assert!(active
            .iter()
            .all(|e| e.system == ProofSystem::Chonk(ChonkRole::Hiding) || e.vk_index.is_some()));
        assert!(!circuits::kernel_hiding::KernelHiding::VK_BYTES.is_empty());
    }

    #[test]
    fn generated_types_flatten_to_the_abi_size() {
        use circuits::kernel_tail::{Inputs, KernelTail, MerklePath, Vk};
        let w = Inputs {
            prev: [Field::from(1u64); 26],
            prev_vk: Vk {
                key: [Field::from(2u64); 151],
                path: MerklePath {
                    index: Field::from(3u64),
                    siblings: [Field::from(4u64); 9],
                },
            },
        };
        let v = KernelTail::witness_inputs(&w, &());
        assert_eq!(v.len(), 26 + 151 + 1 + 9);
        assert_eq!(
            (v[0], v[26], v[26 + 151], v[26 + 152]),
            (1u64, 2, 3, 4).into_fields()
        );
        assert_eq!(KernelTail::LABEL, "kernel_tail");
        assert_eq!(KernelTail::SYSTEM, ProofSystem::Chonk(ChonkRole::Kernel));
        assert_eq!(
            KernelTail::VK_BYTES,
            active(circuits::REGISTRY, "kernel_tail").unwrap().vk
        );
    }

    trait IntoFields {
        fn into_fields(self) -> (Field, Field, Field, Field);
    }
    impl IntoFields for (u64, u64, u64, u64) {
        fn into_fields(self) -> (Field, Field, Field, Field) {
            (self.0.into(), self.1.into(), self.2.into(), self.3.into())
        }
    }
}
